package com.komainos.mantenimiento.controller;
import com.komainos.mantenimiento.dto.*;import com.komainos.mantenimiento.dto.AutomatizacionOrdenRespuesta.*;import com.komainos.mantenimiento.model.*;import com.komainos.mantenimiento.service.*;import com.komainos.mantenimiento.mapper.OrdenMapeador;import com.komainos.ejecucion.config.PropiedadesAutomatizacion;import com.komainos.seguridad.model.*;import com.komainos.shared.dto.*;
import lombok.RequiredArgsConstructor;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.data.domain.Pageable;import org.springframework.data.web.PageableDefault;import java.util.*;import java.time.Instant;
@RestController @RequestMapping("/api") @RequiredArgsConstructor
public class AutomatizacionController {
 private final ServicioGraficosAutomatizacion graficos;
 @GetMapping("/automatizacion/graficos")@PreAuthorize("hasAnyRole('ADMINISTRADOR','OPERADOR')")public ServicioGraficosAutomatizacion.ResumenGraficos graficos(){return graficos.consultar();}
 private final ServicioIndicadoresMantenimiento kpis;
 @GetMapping("/automatizacion/kpis")@PreAuthorize("hasAnyRole('ADMINISTRADOR','OPERADOR')")public ServicioIndicadoresMantenimiento.InformeKpi kpis(@RequestParam(required=false)Instant desde,@RequestParam(required=false)Instant hasta){return kpis.consultar(desde,hasta);}
 private final ServicioConectividad conectividad;
 private final ServicioConsultaAutomatizacion consulta;private final ServicioCicloMantenimiento ciclo;private final ServicioOrquestador orquestador;private final ProcesoAutomatizacion proceso;private final PropiedadesAutomatizacion propiedades;private final ServicioPoliticasCambio politicas;private final ServicioEvaluaciones evaluaciones;private final PuertoProgramacionCambio programacion;private final ServicioDemostracionAutomatizacion demostracion;
 public record ConexionRespuesta(boolean simulado,boolean correcto,String mensaje){}
 @PostMapping("/servidores/{id}/conectividad")@PreAuthorize("hasRole('ADMINISTRADOR')")public ConexionRespuesta conectar(@PathVariable Integer id){var r=conectividad.probar(id);return new ConexionRespuesta(r.simulado(),r.correcto(),r.mensaje());}
 public record ConexionGrupoRespuesta(Integer idServidor,String servidor,boolean simulado,boolean correcto,String mensaje){}
 @PostMapping("/grupos/{id}/conectividad")@PreAuthorize("hasRole('ADMINISTRADOR')")public List<ConexionGrupoRespuesta> conectarGrupo(@PathVariable Integer id){return conectividad.probarGrupo(id).stream().map(r->new ConexionGrupoRespuesta(r.idServidor(),r.servidor(),r.simulado(),r.correcto(),r.mensaje())).toList();}
 public record UsoVersionRespuesta(Integer idOrden,String orden,String servidor,String tarea,EstadoTareaMop estado,Instant inicio,Instant fin){}
 @GetMapping("/scripts/versiones/{id}/ejecuciones")@PreAuthorize("hasAnyRole('ADMINISTRADOR','OPERADOR')")public PaginaRespuesta<UsoVersionRespuesta> usos(@PathVariable Integer id,@PageableDefault(size=20)Pageable p){return PaginaRespuesta.de(consulta.usosVersion(id,p),t->new UsoVersionRespuesta(t.getMop().getDetalle().getOrden().getId(),t.getMop().getDetalle().getOrden().getCodigo(),t.getMop().getDetalle().getServidor().getHostname(),t.getTarea().getNombre(),t.getEstado(),t.getFechaInicio(),t.getFechaFin()));}
 @GetMapping("/automatizacion/modo")public Map<String,Object> modo(){return Map.of("simulado",propiedades.simulada(),"modo",propiedades.modo(),"procesoHabilitado",propiedades.procesoHabilitado());}
 @GetMapping("/ordenes/{id}/automatizacion")public AutomatizacionOrdenRespuesta ficha(@PathVariable Integer id,@AuthenticationPrincipal UsuarioAutenticado u){return AutomatizacionOrdenRespuesta.de(consulta.ficha(id,AlcanceUsuario.de(u)));}
 @PostMapping("/ordenes/{id}/evaluacion")@PreAuthorize("hasRole('ADMINISTRADOR')")public Map<String,String> evaluar(@PathVariable Integer id,@AuthenticationPrincipal UsuarioAutenticado u){ciclo.evaluarOrden(id,AlcanceUsuario.de(u).actor());return Map.of("mensaje","Evaluación previa completada");}
 public record DecisionPeticion(@NotNull EstadoAutorizacion decision,@NotBlank @Size(max=1000)String motivo,Instant fechaPropuesta){}
 @PostMapping("/ordenes/{id}/autorizacion")@PreAuthorize("hasAnyRole('ADMINISTRADOR','RESPONSABLE')")@org.springframework.web.bind.annotation.ResponseStatus(org.springframework.http.HttpStatus.NO_CONTENT) public void decidir(@PathVariable Integer id,@Valid @RequestBody DecisionPeticion p,@AuthenticationPrincipal UsuarioAutenticado u){ciclo.decidir(id,p.decision(),p.motivo(),p.fechaPropuesta(),AlcanceUsuario.de(u));}
 @PostMapping("/ordenes/{id}/aceptar-fecha")@PreAuthorize("hasRole('ADMINISTRADOR')")@org.springframework.web.bind.annotation.ResponseStatus(org.springframework.http.HttpStatus.NO_CONTENT) public void aceptar(@PathVariable Integer id,@AuthenticationPrincipal UsuarioAutenticado u){ciclo.aceptarFecha(id,AlcanceUsuario.de(u).actor());}
 public record ValidarPeticion(boolean conforme,@NotBlank @Size(max=2000)String observaciones){}
 @PostMapping("/ordenes/{id}/validacion")@PreAuthorize("hasRole('RESPONSABLE')")@org.springframework.web.bind.annotation.ResponseStatus(org.springframework.http.HttpStatus.NO_CONTENT) public void validar(@PathVariable Integer id,@Valid @RequestBody ValidarPeticion p,@AuthenticationPrincipal UsuarioAutenticado u){ciclo.validar(id,p.conforme(),p.observaciones(),AlcanceUsuario.de(u));}
 public record MotivoPeticion(@NotBlank @Size(max=1000)String motivo){}
 @PostMapping("/ordenes/{id}/cierre-sin-implementacion")@PreAuthorize("hasRole('ADMINISTRADOR')")@org.springframework.web.bind.annotation.ResponseStatus(org.springframework.http.HttpStatus.NO_CONTENT) public void cerrar(@PathVariable Integer id,@Valid @RequestBody MotivoPeticion p,@AuthenticationPrincipal UsuarioAutenticado u){ciclo.cerrarSinImplementacion(id,p.motivo(),AlcanceUsuario.de(u).actor());}
 public record InmediataPeticion(Integer idServidor,Integer idGrupo,boolean confirmarFueraVentana,@NotBlank @Size(max=1000)String motivo){}
 @PostMapping("/automatizacion/inmediata")@PreAuthorize("hasRole('ADMINISTRADOR')")public ReferenciaSimple inmediata(@Valid @RequestBody InmediataPeticion p,@AuthenticationPrincipal UsuarioAutenticado u){var actor=AlcanceUsuario.de(u).actor();var o=programacion.inmediata(p.idServidor(),p.idGrupo(),p.confirmarFueraVentana(),p.motivo(),null,actor);ciclo.evaluarOrden(o.getId(),actor);return new ReferenciaSimple(o.getId(),o.getCodigo());}
 @PostMapping("/automatizacion/procesar")@PreAuthorize("hasRole('ADMINISTRADOR')")public Map<String,Integer> procesar(){return Map.of("despachados",proceso.procesar());}
 @PostMapping("/automatizacion/ejecutar-cola")@PreAuthorize("hasRole('ADMINISTRADOR')")public Map<String,Integer> ejecutar(){return Map.of("despachados",orquestador.despachar());}
 @PostMapping("/automatizacion/demostracion")@PreAuthorize("hasRole('ADMINISTRADOR')")public Map<String,Integer> demostrar(@AuthenticationPrincipal UsuarioAutenticado u){return demostracion.cargar(AlcanceUsuario.de(u).actor());}
 @GetMapping("/automatizacion/sala")@PreAuthorize("hasAnyRole('ADMINISTRADOR','OPERADOR')")public PaginaRespuesta<OrdenResumenRespuesta> sala(@RequestParam(required=false)EtapaOrden etapa,@RequestParam(required=false)Integer idEntorno,@RequestParam(required=false)Integer idCriticidad,@PageableDefault(size=20)Pageable p){return PaginaRespuesta.de(consulta.sala(etapa,idEntorno,idCriticidad,p),OrdenMapeador::resumen);}
 public record ColaRespuesta(Integer idDetalle,Integer idOrden,String orden,String servidor,String prioridad,EstadoDetalleOrden estado,int posicion,boolean piloto,Instant inicioPrevisto,Instant inicioReal){}
 @GetMapping("/automatizacion/cola")@PreAuthorize("hasAnyRole('ADMINISTRADOR','OPERADOR')")public PaginaRespuesta<ColaRespuesta> cola(@PageableDefault(size=20)Pageable p){var pagina=consulta.cola(p);int[] posicion={(int)p.getOffset()};return PaginaRespuesta.de(pagina,d->new ColaRespuesta(d.getId(),d.getOrden().getId(),d.getOrden().getCodigo(),d.getServidor().getHostname(),d.getOrden().prioridad().name(),d.getEstado(),++posicion[0],d.isEsServidorPiloto(),d.getFechaPrevistaInicio(),d.getFechaRealInicio()));}
 @GetMapping("/automatizacion/indicadores")@PreAuthorize("hasAnyRole('ADMINISTRADOR','OPERADOR')")public Map<String,Long> indicadores(){return consulta.indicadores();}
 @PostMapping("/servidores/{id}/revision")@PreAuthorize("hasRole('ADMINISTRADOR')")public Analisis revisar(@PathVariable Integer id,@AuthenticationPrincipal UsuarioAutenticado u){return Analisis.de(ciclo.revisar(id,AlcanceUsuario.de(u).actor()));}
 @GetMapping("/servidores/{id}/evaluaciones")public PaginaRespuesta<Analisis> historial(@PathVariable Integer id,@PageableDefault(size=20)Pageable p,@AuthenticationPrincipal UsuarioAutenticado u){return PaginaRespuesta.de(evaluaciones.historial(id,AlcanceUsuario.de(u),p),Analisis::de);}
 @GetMapping("/politicas-cambio")@PreAuthorize("hasAnyRole('ADMINISTRADOR','OPERADOR')")public PaginaRespuesta<PoliticaCambioRespuesta> politicas(@PageableDefault(size=20)Pageable p){return PaginaRespuesta.de(politicas.listar(p),r->PoliticaCambioRespuesta.de(r,politicas.notificaciones(r.getId())));}
 @PostMapping("/politicas-cambio")@PreAuthorize("hasRole('ADMINISTRADOR')")public PoliticaCambioRespuesta crear(@Valid @RequestBody PoliticaCambioPeticion p,@AuthenticationPrincipal UsuarioAutenticado u){return guardar(null,p,u);}
 @PutMapping("/politicas-cambio/{id}")@PreAuthorize("hasRole('ADMINISTRADOR')")public PoliticaCambioRespuesta editar(@PathVariable Integer id,@Valid @RequestBody PoliticaCambioPeticion p,@AuthenticationPrincipal UsuarioAutenticado u){return guardar(id,p,u);}
 private PoliticaCambioRespuesta guardar(Integer id,PoliticaCambioPeticion p,UsuarioAutenticado u){var r=politicas.guardar(id,new ServicioPoliticasCambio.DatosRegla(p.idEntorno(),p.nivelAfectacion(),p.requiereResponsable(),p.requiereAdministrador(),p.activo(),p.notificaciones(),p.versionEsperada()),AlcanceUsuario.de(u).actor());return PoliticaCambioRespuesta.de(r,politicas.notificaciones(r.getId()));}
 @GetMapping("/incidencias")@PreAuthorize("hasAnyRole('ADMINISTRADOR','OPERADOR')")public PaginaRespuesta<Problema> incidencias(@RequestParam(required=false)EstadoIncidencia estado,@RequestParam(required=false)Integer idServidor,@RequestParam(required=false)String texto,@PageableDefault(size=20)Pageable p){return PaginaRespuesta.de(consulta.incidencias(estado,idServidor,texto,p),Problema::de);}
 @GetMapping("/incidencias/{id}")@PreAuthorize("hasAnyRole('ADMINISTRADOR','OPERADOR')")public Problema incidencia(@PathVariable Integer id){return Problema.de(consulta.incidencia(id));}
 public record AtenderPeticion(@NotBlank @Size(max=10000)String diagnostico,@NotBlank @Size(max=10000)String acciones,@NotBlank @Size(max=1000)String resultado,boolean cerrar){}
 @PutMapping("/incidencias/{id}")@PreAuthorize("hasRole('ADMINISTRADOR')")public Problema atender(@PathVariable Integer id,@Valid @RequestBody AtenderPeticion p,@AuthenticationPrincipal UsuarioAutenticado u){return Problema.de(ciclo.atender(id,p.diagnostico(),p.acciones(),p.resultado(),p.cerrar(),AlcanceUsuario.de(u).actor()));}
}
